 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    moves = {1: (-1, 2), 2: (0, -4), 3: (3, 0), 6: (-6, 0)}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in moves:
                continue
            dr, dc = moves[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            # Color 1's route turns at the destination column; the other
            # markers travel straight along their displacement.
            if color == 1:
                step = 1 if dc > 0 else -1
                for cc in range(c + step, ec + step, step):
                    if (r, cc) != (r, c):
                        out[r][cc] = 5
                step = 1 if dr > 0 else -1
                for rr in range(r + step, er, step):
                    out[rr][ec] = 5
            elif dr:
                step = 1 if dr > 0 else -1
                for rr in range(r + step, er, step):
                    out[rr][c] = 5
            else:
                step = 1 if dc > 0 else -1
                for cc in range(c + step, ec, step):
                    out[r][cc] = 5
            out[er][ec] = color
    return out
