                path = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
                end = path[-1]
            elif color == 2:
                path = [(r, c - k) for k in range(1, 5)]
                end = path[-1]
            elif color == 3:
                path = [(r + k, c) for k in range(1, 4)]
                end = path[-1]
            elif color == 6:
                path = [(r - k, c) for k in range(1, 7)]
                end = path[-1]
            else:
                continue
            if all(0 <= rr < h and 0 <= cc < w for rr, cc in path):
                sources.append((color, (r, c), path, end))

    # Draw each ray. Its far endpoint retains the source color; the path
    # between origin and endpoint is color 5.
    for color, origin, path, end in sources:
        for cell in path[:-1]:
            rr, cc = cell
            out[rr][cc] = 5
        rr, cc = end
        out[rr][cc] = color

    # Where a 2 ray crosses a vertical 3/6 ray, mark the collision and send
    # the resulting 4 diagonally down-left to the edge.
    for color_a, _, path_a, _ in sources:
